mapper.select:
select distinct b.subject_no id, b.subject_name text from bok_subject b where 1=1 and b.subject_level = #{subjectLevel,jdbcType=VARCHAR}
and b.bookset_id in
#{item}
AND (lower(b.subject_no) like '%' || lower(#{search}) || '%' OR lower(b.subject_name) like '%' || lower(#{search}) || '%')
order by b.subject_type

mapper.delete:
delete from BOK_BUSS_DETSUB b where 1=1
and b.DETAIL_SUBJECT_NO = #{detailSubjectNo,jdbcType=VARCHAR}
and b.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}

mapper.update:
update BOK_DETAIL_ID b
set b.DETAIL_SUBJECT_NO_TAIL = #{detailSubjectNoTail,jdbcType=VARCHAR},
b.DETAIL_SUBNAME_TAIL = #{detailSubnameTail,jdbcType=VARCHAR},
b.UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
b.UPDATE_TIME = #{updateTime,jdbcType=VARCHAR}
where b.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and b.BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}

update BOK_BOOKDETAIL_ALL b
set b.DETAIL_SUBJECT_NO = #{detailSubjectNo,jdbcType=VARCHAR},
b.UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
b.UPDATE_TIME = #{updateTime,jdbcType=VARCHAR}
where b.SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}
and b.BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}
and b.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}

update BOK_BOOKDETAIL_CURRENT b
set b.DETAIL_SUBJECT_NO = #{detailSubjectNo,jdbcType=VARCHAR},
b.UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
b.UPDATE_TIME = #{updateTime,jdbcType=VARCHAR}
where b.SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}
and b.BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}
and b.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
